from .message_handling import (SMessageAddress, SMessageHeader,
                               RequestMessage, ResponseMessage, Manager,
                               register_message, register_trace_ind, u32)

from .sack_reflection_interface import EBrowserReportType, EBrowserPeriodicityScale

from ..commons import LOGGER


@register_message
class BrowserStartGeneralReportReq(RequestMessage):
    """
    https://confluence.int.net.nokia.com/display/MBBHBSCOP5/DCM+Measurements+Interface
    """
    id = 0x1e0d

    dynamicDataLength = 6

    _fields_ = [
        ('header', SMessageHeader),
        # Report Descriptor
        ('requestor', SMessageAddress),
        ('reportName', u32),
        ('contextId', u32),
        ('procedureId', u32),
        ('priority', u32),

        # ReportCharacteristics
        ('reportType', u32),
        ('periodicityScale', u32),
        ('reportPeriod', u32),
        ('startSfn', u32),
        ('reportingDuration', u32),
        ('reportGranularityScale', u32),
        ('granularity', u32),
        ('decimationFactor', u32),
        ('filter', u32),
        ('threshold1', u32),
        ('threshold2', u32),
        ('timeScale', u32),
        ('time1', u32),
        ('time2', u32),

        # Database Keys
        ('numberOfAssociatedObjects', u32),

        # dynamic part
        ('dynamicData', u32 * dynamicDataLength)
    ]

    def __init__(self, board, cpu, *args, **kwargs):
        super(BrowserStartGeneralReportReq, self).__init__(board, cpu, *args, **kwargs)
        self.reportType = EBrowserReportType.EBrowserReportType_PeriodicCollected
        self.periodicityScale = EBrowserPeriodicityScale.EBrowserTimeScale_RadioFrame
        self.reportPeriod = 100  # 0x64  # 100 frames, 1 second
        self.startSfn = 0xFFF0  # SPPE_UNSYNC_SFN
        self.reportGranularityScale = 0  # frame
        self.granularity = 1  # 1 frame
        # if some vector gets too big, take only every M-th sample, where M is the decimation factor
        self.decimationFactor = 1
        self.numberOfAssociatedObjects = 0


@register_message
class BrowserStartGeneralReportResp(ResponseMessage):
    id = 0x1e13

    _fields_ = [
        ('header', SMessageHeader),
        ('reportName', u32),
        ('status', u32),
        ('contextId', u32),
        ('procedureId', u32)
    ]


