@register_trace_ind
@register_message
class BrowserGeneralReportInd(ResponseMessage):
    """
    Reporting measurement indicator
    https://confluence.int.net.nokia.com/pages/viewpage.action?pageId=252026498#DCMMeasurementsInterface-3.7BrowserGeneralReportInd
    """
    id = 0x1e0f

    _fields_ = [
        ('header', SMessageHeader),
        ('timeStamp', u32),
        ('contextId', u32),
        ('procedureId', u32),
        ('itemCount', u32),
        ('itemSize', u32),
        # dynamic part
        ('reportData', u32 * 1)
    ]


class BrowserGeneralReportIndSink(Manager):
    def __init__(self, cookie=None):
        assert isinstance(cookie, tuple)
        super(BrowserGeneralReportIndSink, self).__init__()
        self._cookies = [cookie]
        self._register()

        self.all_inds = []

    def digest(self, byte_stream):
        status_ok = self._check(byte_stream)
        if status_ok:
            self.all_inds.append(byte_stream)

    def _set_cookies(self):
        # already set in __init__
        pass

    @staticmethod
    def _check(byte_stream):

        msg = BrowserGeneralReportInd().deserialize(byte_stream)

        item_count = msg.itemCount
        item_size = msg.itemSize
        header = msg.header

        status = 1
        if item_count > 65535 or item_size > 65535:
            LOGGER.warning("Invalid BrowserGeneralReportInd with itemCount({}) and itemSize({}) for:\n{}".format(
                item_count, item_size, header))
            status = 0
        return status
